import {useState} from 'react';
import {control} from '../shared/RoleFrame.tsx';
function embedSource(value?:string){try{const url=new URL(value??'');if(url.protocol!=='https:'||!['www.figma.com','figma.com','embed.figma.com'].includes(url.hostname)||url.username||url.password)return null;const match=url.pathname.match(/^\/(design|proto|board|file)\/([A-Za-z0-9]+)(?:\/|$)/);if(!match)return null;const embed=new URL(`https://embed.figma.com/${match[1]==='file'?'design':match[1]}/${match[2]}`);embed.searchParams.set('embed-host','gitfolio');for(const key of ['node-id','starting-point-node-id']){const value=url.searchParams.get(key);if(value)embed.searchParams.set(key,value);}return embed.href;}catch{return null;}}
export function PrototypeEmbed({url,label,interactive}:{url?:string;label?:string;interactive:boolean}){const[loaded,setLoaded]=useState(false),source=embedSource(url);if(!source)return null;return <div className="mt-6 border-t border-[var(--rp-border)] pt-5"><p className="rp-meta">{label??'Figma prototype reference'}</p>{loaded?<iframe src={source} title={label??'Figma prototype'} className="mt-4 h-[420px] w-full rounded-lg border border-[var(--rp-border)]" loading="lazy" referrerPolicy="no-referrer" sandbox="allow-scripts allow-same-origin allow-forms" allowFullScreen/>:<button type="button" className={`${control} mt-3`} disabled={!interactive} onClick={()=>setLoaded(true)}>Load Figma reference ↗</button>}<p className="rp-demo-note">External Figma content loads when you choose to open it.</p></div>;}

