import { useDeferredValue, useEffect, useId, useRef, useState } from 'react';
import type { SecurityWidget } from '../shared/contracts.ts';
import { control, DemoNote, SafeLink } from '../shared/RoleFrame.tsx';
type Finding = SecurityWidget['findings'][number];
const severityClass = { Critical:'text-[var(--rp-danger)] border-[var(--rp-danger)]',High:'text-[var(--rp-warning)] border-[var(--rp-warning)]',Medium:'text-[var(--rp-accent)] border-[var(--rp-accent)]' };
export function SecurityExplorer({data,interactive=true}:{data:SecurityWidget;interactive?:boolean}) {
  const [query,setQuery]=useState(''),[severity,setSeverity]=useState('All'),[selected,setSelected]=useState<Finding|null>(null);
  const search=useDeferredValue(query.trim().toLowerCase()),titleId=useId(),dialog=useRef<HTMLDialogElement>(null),opener=useRef<HTMLButtonElement|null>(null),searchInput=useRef<HTMLInputElement>(null);
  const findings=data.findings.filter((finding)=>(severity==='All'||finding.severity===severity)&&[finding.id,finding.title,finding.target,finding.status,finding.summary].join(' ').toLowerCase().includes(search));
  useEffect(()=>{if(selected&&!dialog.current?.open)dialog.current?.showModal();if(!selected&&dialog.current?.open)dialog.current.close();},[selected]);
  function close(){dialog.current?.close();setSelected(null);if(opener.current?.isConnected)opener.current.focus();else searchInput.current?.focus();}
  return <div data-widget="security" className="mt-6"><fieldset disabled={!interactive} className="rp-security-filters"><legend className="sr-only">Finding filters</legend><label className="min-w-0 flex-1 text-[10px] uppercase tracking-widest text-[var(--rp-muted)]">Search security findings<input ref={searchInput} type="search" value={query} placeholder="Identifier, target, or finding…" className="mt-2 min-h-11 w-full rounded border border-[var(--rp-border)] bg-[var(--rp-bg)] px-3 text-xs text-[var(--rp-text)]" onChange={(event)=>setQuery(event.target.value)} /></label><div className="flex flex-wrap gap-2" role="group" aria-label="Severity">{['All','Critical','High','Medium'].map((value)=><button type="button" key={value} className={control} aria-pressed={severity===value} onClick={()=>setSeverity(value)}>{value}</button>)}</div></fieldset>
    <p className="rp-meta" role="status">{findings.length} of {data.findings.length} example findings</p><div className="rp-security-log" role="list" aria-label="Security audit log">{findings.map((finding)=><article role="listitem" key={finding.id} className="rp-security-finding"><div><span className={`inline-flex rounded border px-2 py-1 text-[10px] ${severityClass[finding.severity]}`}>{finding.severity}</span><p className="rp-meta">{finding.id}</p></div><div><h3 className="text-sm font-semibold">{finding.title}</h3><p className="rp-meta">{finding.target}</p></div><div><p className="text-[10px] text-[var(--rp-success)]">{finding.status}</p><button type="button" disabled={!interactive} aria-label={`Open finding ${finding.id}`} className="mt-2 min-h-11 text-xs text-[var(--rp-accent)] underline underline-offset-4" onClick={(event)=>{opener.current=event.currentTarget;setSelected(finding);}}>View breakdown ↗</button></div></article>)}</div>{!findings.length&&<p className="my-6 text-sm text-[var(--rp-muted)]">No findings match. Try another keyword or severity.</p>}<DemoNote>Simulated audit log · Lab identifiers are examples · No scans are performed</DemoNote>
    <dialog ref={dialog} aria-labelledby={titleId} className="rp-security-drawer" onCancel={()=>{setSelected(null);}} onClose={()=>{setSelected(null);if(opener.current?.isConnected)opener.current.focus();}}>{selected&&<><div className="flex items-start justify-between gap-4"><span className={`rounded border px-2 py-1 text-xs ${severityClass[selected.severity]}`}>{selected.severity}</span><button type="button" className={control} onClick={close}>Close finding</button></div><p className="rp-kicker mt-8">{selected.id} / {selected.status}</p><h3 id={titleId} className="text-2xl font-semibold">{selected.title}</h3><p className="rp-meta">{selected.target}</p><h4 className="mt-8 text-xs font-semibold uppercase tracking-widest">Scope & risk</h4><p className="rp-copy">{selected.summary}</p><h4 className="mt-8 text-xs font-semibold uppercase tracking-widest">Resolution & verification</h4><p className="rp-copy">{selected.resolution}</p>{selected.reference&&<SafeLink url={selected.reference} className="rp-action">Read the public advisory ↗</SafeLink>}<DemoNote>This local breakdown does not disclose a live vulnerability or claim original discovery credit.</DemoNote></>}</dialog>
  </div>;
}

